/usr/bin/bash -lc "python - <<'PY'
import csv,json,math,re
with open('market.csv',newline='',encoding='utf-8') as f: rows=list(csv.DictReader(f))
active={r['qid']:r for r in rows if r['is_resolved'].lower()=='false'}
with open('memory/baseline_forecasts.json',encoding='utf-8') as f: b=json.load(f)
errors=[]
missing=sorted(set(active)-set(b))
for qid in active:
 o=b.get(qid,{})
 if not (1 <= len(o) <= 5): errors.append((qid,'outcome_count',len(o)))
 s=sum(o.values())
 if not all(isinstance(p,(int,float)) and math.isfinite(p) and 0<=p<=1 for p in o.values()): errors.append((qid,'probability'))
 if s>1+1e-12: errors.append((qid,'sum',s))
 if any(k in {'Unknown','TBD','Other','N/A'} for k in o): errors.append((qid,'placeholder'))
 if any(not k.isascii() for k in o): errors.append((qid,'non_ascii'))
market_preds={qid:json.loads(r['my_prediction']) for qid,r in active.items()}
drift=[qid for qid in active if b[qid]"'!=market_preds[qid]]
print('"'market_total',len(rows),'active',len(active),'resolved',len(rows)-len(active))
print('baseline_total',len(b),'active_missing',missing)
print('validation_errors',errors)
print('expected_day_updates',drift)
for qid in drift: print(qid,b[qid], 'sum=',sum(b[qid].values()))
PY"

